/**
 * A1 placeholder map stamps (arena, trainer, rest stop) and badge art, generated by code
 * in the same paper-and-ink look as the creature markers. Original shapes only.
 */
const INK = '#3b2a20';
const PAPER = '#fbf4e6';

/**
 * POI stamps (arena, trainer, rest stop, market) and Town Map destination stamps (forest,
 * field, lake, town: what a zone mostly is, D165).
 */
export type StampKind =
  'arena' | 'trainer' | 'restStop' | 'market' | 'forest' | 'field' | 'lake' | 'town';
export const STAMP_KINDS: StampKind[] = [
  'arena',
  'trainer',
  'restStop',
  'market',
  'forest',
  'field',
  'lake',
  'town',
];

const STAMP_COLOUR: Record<StampKind, string> = {
  arena: '#c8553d',
  trainer: '#3d6fa8',
  restStop: '#4f9a63',
  market: '#d08a2e',
  forest: '#3f7d4a',
  field: '#a9a243',
  lake: '#3d8fb8',
  town: '#9a6b8a',
};

/** Postage-stamp edge: a rounded square with scalloped perforation dots. */
function stampFrame(colour: string): string {
  const dots: string[] = [];
  for (let i = 0; i < 7; i++) {
    const p = 8 + i * 8;
    dots.push(
      `<circle cx="${p}" cy="4" r="2.6"/>`,
      `<circle cx="${p}" cy="60" r="2.6"/>`,
      `<circle cx="4" cy="${p}" r="2.6"/>`,
      `<circle cx="60" cy="${p}" r="2.6"/>`,
    );
  }
  return [
    `<rect x="4" y="4" width="56" height="56" rx="5" fill="${PAPER}" stroke="${INK}" stroke-width="2.5"/>`,
    `<g fill="#f3ead6">${dots.join('')}</g>`,
    `<rect x="10" y="10" width="44" height="44" rx="3" fill="${colour}" stroke="${INK}" stroke-width="2"/>`,
  ].join('');
}

